files.content:
:root {
  --brand-color: #6dc1fd;
}

* {
  box-sizing: border-box;
}

html {
  height: 100vh;
}

body {
  display: grid;
  place-items: center;
  gap: 25px;
  min-width: 850px;
  min-height: 100%;
  margin: 0;
  padding: 50px;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  background-image: url(https://code.s3.yandex.net/web-code/images/dotted-l.svg);
}

.card {
  width: 50%;
  min-width: 350px;
  border: 1px solid black;
  padding: 50px;
  background-color: #fff;
}

.card__shadow {
  filter: drop-shadow(10px 10px var(--brand-color));
}

.card__border {
  border: 3px solid var(--brand-color);
}

.card__background {
  background-color: var(--brand-color);
}
